-- Playable race creation data generated from race_registry.json.
-- The update owns IDs 1-28 and never uses reserved NPC IDs 32-42.

DELETE FROM `playercreateinfo` WHERE `race` BETWEEN 1 AND 27;

DELETE FROM `playercreateinfo_action` WHERE `race` BETWEEN 1 AND 27;

DELETE FROM `charstartoutfit_dbc` WHERE `RaceID` BETWEEN 1 AND 27;

DELETE FROM `player_race_stats` WHERE `Race` BETWEEN 14 AND 27;

DELETE FROM `playercreateinfo_skills` WHERE `raceMask` IN (16384, 32768, 65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608, 16777216, 33554432, 67108864);

DELETE FROM `playercreateinfo_spell_custom` WHERE `racemask` IN (16384, 32768, 65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608, 16777216, 33554432, 67108864);

DELETE FROM `skillraceclassinfo_dbc` WHERE `ID` BETWEEN 1200 AND 1209;
